bc4-ac9d-5ffe3ac877be","description":"Oink","correct_answer":false}]},{"id":"01a21904-ad08-74e7-9b8a-f9e44e3e03c9","category":"01a21312-b489-7095-8a30-44480fe2c4f5","question":"On a sailing ship, which side is called \'port\'?","difficulty":1,"explanation":"Left is the port side; ships mark it with a red navigation light, while starboard is marked green.","alternatives":[{"id":"01a21904-ad08-778f-8686-502d8c568fee","description":"Left","correct_answer":true},{"id":"01a21904-ad08-772c-a29b-34e55a60790b","description":"Right","correct_answer":false},{"id":"01a21904-ad08-78b0-ad40-2c41ca37db30","description":"Front (bow)","correct_answer":false},{"id":"01a21904-ad08-70f4-9d50-62a82a8070ea","description":"Rear (stern)","correct_answer":false}]},{"id":"01a21904-ad08-7eac-aa25-fd74a7e4f26c","category":"01a21312-b489-7095-8a30-44480fe2c4f5","question":"What word is used in the NATO Phonetic Alphabet for the letter D?","difficulty":1,"explanation":"Delta is the NATO code word for D. The standardized words help make letters clear over radio and telephone connections.","alternatives":[{"id":"01a21904-ad08-71b7-ac2a-457e8dc0c7ba","description":"Delta","correct_answer":true},{"id":"01a21904-ad08-7da9-b04e-b1e29c5457b5","description":"Dog","correct_answer":false},{"id":"01a21904-ad08-7221-a759-389e4760f427","description":"Danube","correct_answer":false},{"id":"01a21904-ad08-744a-a502-b754d909142b","description":"Dig","correct_answer":false}]}]', true);

